# Re-enable 8.3 Short File Name Generation Write-Host "Re-enabling 8.3 short file name generation on all NTFS volumes..." -ForegroundColor Cyan $volumes = Get-Volume | Where-Object { $_.FileSystem -eq "NTFS" -and $_.DriveLetter } foreach ($vol in $volumes) { $drive = $vol.DriveLetter + ":" fsutil 8dot3name set $drive 0 2>&1 | Out-Null Write-Host " Enabled 8.3 naming on drive $drive" -ForegroundColor Gray } Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem" -Name "NtfsDisable8dot3NameCreation" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue Write-Host "8.3 short file name generation has been re-enabled." -ForegroundColor Green